--- a/services/checkout/charge.go
+++ b/services/checkout/charge.go
@@ -41,7 +41,18 @@ func (s *Server) charge(ctx context.Context, req *pb.ChargeRequest) (*pb.ChargeResponse, error) {
-	return s.payments.Charge(ctx, req)
+	if !s.flags.Enabled("charge_retry_enabled") {
+		return s.payments.Charge(ctx, req)
+	}
+	var lastErr error
+	for attempt := 0; attempt < 2; attempt++ {
+		resp, err := s.payments.Charge(ctx, req)
+		if err == nil || !errors.Is(err, ErrTransient) {
+			return resp, err
+		}
+		lastErr = err
+		time.Sleep(time.Duration(attempt+1) * 50 * time.Millisecond)
+	}
+	return nil, lastErr
 }

